  // ---- パドル ----
  const paddle = { w: 96, h: 14, x: W / 2 - 48, y: H - 34, speed: 520 };

  // ---- ボール ----
  const ball = { x: 0, y: 0, r: 7, dx: 0, dy: 0, speed: 300, stuck: true };

  // ---- ブロック ----
  let blocks = [];
  const ROW_COLORS = ['#ff5d5d', '#ff9a3d', '#ffd75d', '#6ee86e', '#5db8ff', '#b07dff'];

  function buildBlocks() {
    blocks = [];
    const cols = 10;
    const rows = Math.min(4 + level, 8);
    const margin = 30, top = 50, gap = 6;
    const bw = (W - margin * 2 - gap * (cols - 1)) / cols;
    const bh = 20;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // レベルに応じて一部ブロックを頑丈にする
        const tough = level >= 2 && (r + c) % 5 === 0;
        blocks.push({
          x: margin + c * (bw + gap),
          y: top + r * (bh + gap),
          w: bw, h: bh,
          color: ROW_COLORS[r % ROW_COLORS.length],
          hp: tough ? 2 : 1,
          points: (rows - r) * 10
        });
      }
    }
  }

  function resetBall() {
    ball.stuck = true;
    ball.speed = 260 + level * 25;
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
    ball.dx = 0;
    ball.dy = 0;
  }

  function launchBall() {
    if (!ball.stuck) return;
    ball.stuck = false;
    const angle = -Math.PI / 2 + (Math.random() * 0.6 - 0.3);
    ball.dx = Math.cos(angle) * ball.speed;
    ball.dy = Math.sin(angle) * ball.speed;
  }

  // ---- 入力 ----
